/// Cross-harness session import (issue #1562): the typed foreign-record
/// union, the per-session scan result, and the import bounds.
///
/// Adapters (omp, claude) stream foreign JSONL stores read-only into
/// [ForeignRecord]s; the pure mapper ([mapForeignSession]) turns them into
/// FA append plans; the runner ([runImport]) writes through
/// `JsonlSessionRepo.create` + `Session.append*` only. Foreign stores are
/// never written.
library;

/// Import bounds (issue #1561 open questions 1 + 4, pinned at
/// implementation): files over [maxFileBytes] are refused before reading,
/// lines over [maxLineBytes] skip-with-count, image blobs embed only when
/// the file is present and at most [maxImageBytes], and the TUI keyword
/// search indexes at most [searchIndexBytes] of text per session.
final class ImportLimits {
  /// Creates [ImportLimits]. Defaults: 512 MiB per file, 16 MiB per line,
  /// 1 MiB per image blob, 64 KiB of search text per session.
  const ImportLimits({
    this.maxFileBytes = 512 * 1024 * 1024,
    this.maxLineBytes = 16 * 1024 * 1024,
    this.maxImageBytes = 1 * 1024 * 1024,
    this.searchIndexBytes = 64 * 1024,
  });

  /// Refusal threshold for one foreign session file (checked from the file
  /// size before any read).
  final int maxFileBytes;

  /// Skip threshold for one JSONL line.
  final int maxLineBytes;

  /// Embed threshold for one image blob (oversized blobs become counted
  /// placeholders).
  final int maxImageBytes;

  /// Search-text cap per session for the `/import` picker keyword index.
  final int searchIndexBytes;
}

/// A block of a foreign message's content.
///
/// Foreign content blocks are kept typed but lossless: anything the mapper
/// cannot place lands as [ForeignUnknownBlock] and is skipped-with-count,
/// never silently dropped.
sealed class ForeignContent {
  const ForeignContent();
}

/// Plain text.
final class ForeignText extends ForeignContent {
  /// Creates [ForeignText].
  const ForeignText(this.text);

  /// The text itself.
  final String text;
}

/// Model reasoning produced before or alongside the answer.
final class ForeignThinking extends ForeignContent {
  /// Creates [ForeignThinking].
  const ForeignThinking(this.thinking, {this.signature});

  /// The reasoning text.
  final String thinking;

  /// Provider-specific opaque signature, when the foreign record carried one.
  final String? signature;
}

/// A model request to invoke a tool.
final class ForeignToolCall extends ForeignContent {
  /// Creates [ForeignToolCall].
  const ForeignToolCall({
    required this.id,
    required this.name,
    required this.arguments,
    this.partialArguments,
  });

  /// The call id a `toolResult` pairs with.
  final String id;

  /// The tool name.
  final String name;

  /// Parsed arguments, when the foreign record had a complete object.
  final Map<String, dynamic> arguments;

  /// Raw, not-yet-complete JSON argument text (interrupted streams).
  final String? partialArguments;
}

/// An image: embedded base64 (within bounds) or a counted placeholder.
final class ForeignImage extends ForeignContent {
  /// Creates an embedded image.
  const ForeignImage({required this.base64Data, required this.mimeType})
    : missingReason = null;

  /// Creates a skipped-image placeholder carrying the reason.
  const ForeignImage.skipped(this.missingReason)
    : base64Data = null,
      mimeType = null;

  /// Base64 image data, null when skipped.
  final String? base64Data;

  /// Declared MIME type (labeling only — never drives behavior).
  final String? mimeType;

  /// Why the image was skipped (missing blob, oversized, undecodable).
  final String? missingReason;
}

/// A content block the adapter does not model.
final class ForeignUnknownBlock extends ForeignContent {
  /// Creates [ForeignUnknownBlock].
  const ForeignUnknownBlock(this.type, this.raw);

  /// The foreign block `type` string.
  final String type;

  /// The raw block JSON map.
  final Map<String, dynamic> raw;
}

/// One foreign record, typed.
///
/// The union is deliberately shallow (per the retracted-IR ruling on the
/// GOAL card): adapters parse only what the mapper consumes; unmapped
/// foreign types land as [ForeignUnhandled] and map to FA `custom` entries.
sealed class ForeignRecord {
  /// Creates [ForeignRecord].
  const ForeignRecord({required this.lineNumber});

  /// 1-based line number in the foreign file (diagnostics only).
  final int lineNumber;
}

/// A title slot or `title_change` audit record.
final class ForeignTitleSlot extends ForeignRecord {
  /// Creates [ForeignTitleSlot].
  const ForeignTitleSlot({
    required super.lineNumber,
    required this.title,
    required this.source,
  });

  /// The title text.
  final String title;

  /// `user` or `auto` — user titles beat auto titles regardless of order.
  final String source;
}

/// The session header (`type:"session"`).
final class ForeignHeader extends ForeignRecord {
  /// Creates [ForeignHeader].
  const ForeignHeader({
    required super.lineNumber,
    required this.id,
    required this.cwd,
    required this.version,
    this.title,
    this.titleSource,
  });

  /// Foreign session id.
  final String id;

  /// Working directory recorded in the header (empty when absent).
  final String cwd;

  /// Format version (advisory — adapters tolerate 1-3).
  final int version;

  /// Legacy inline title (pre-title-slot files).
  final String? title;

  /// Legacy inline title source.
  final String? titleSource;
}

/// A conversation message (`type:"message"`).
final class ForeignMessage extends ForeignRecord {
  /// Creates [ForeignMessage].
  const ForeignMessage({
    required super.lineNumber,
    required this.role,
    required this.contents,
    required this.rawMessage,
    this.toolCallId,
    this.toolName,
    this.isError = false,
    this.model,
    this.provider,
    this.api,
    this.usage,
    this.stopReason,
    this.errorMessage,
  });

  /// camelCase foreign role (`user`, `developer`, `assistant`,
  /// `toolResult`, `bashExecution`, ...).
  final String role;

  /// Parsed content blocks.
  final List<ForeignContent> contents;

  /// The raw `message` JSON map (custom-entry fallbacks carry it verbatim).
  final Map<String, dynamic> rawMessage;

  /// `toolResult` pairing key.
  final String? toolCallId;

  /// `toolResult` tool name.
  final String? toolName;

  /// `toolResult` failure flag.
  final bool isError;

  /// Assistant model id, when the record carried one.
  final String? model;

  /// Assistant provider id, when the record carried one.
  final String? provider;

  /// Assistant API dialect, when the record carried one.
  final String? api;

  /// Raw usage map, when present (mapped best-effort onto FA [Usage]).
  final Map<String, dynamic>? usage;

  /// Raw terminal stop reason string, when present.
  final String? stopReason;

  /// Raw error message, when present.
  final String? errorMessage;
}

/// A `model_change` record.
final class ForeignModelChange extends ForeignRecord {
  /// Creates [ForeignModelChange].
  const ForeignModelChange({required super.lineNumber, required this.model});

  /// The model string verbatim (e.g. `zai/glm-5.3`).
  final String model;
}

/// A `thinking_level_change` record.
final class ForeignThinkingLevelChange extends ForeignRecord {
  /// Creates [ForeignThinkingLevelChange].
  const ForeignThinkingLevelChange({
    required super.lineNumber,
    required this.level,
  });

  /// The level, passed through (null/medium/high/xhigh/max or the raw
  /// foreign value).
  final String level;
}

/// A `compaction` record (summary verbatim; optional fields counted).
final class ForeignCompaction extends ForeignRecord {
  /// Creates [ForeignCompaction].
  const ForeignCompaction({
    required super.lineNumber,
    required this.summary,
    required this.droppedFields,
  });

  /// The summary text.
  final String summary;

  /// Optional fields present on the record but dropped (counted, never
  /// silent).
  final List<String> droppedFields;
}

/// A `custom` record: `customType` preserved byte-exact through the mapper.
final class ForeignCustom extends Fo…

content.text:
/// Adapter plumbing for the cross-harness importer (issue #1562): the
/// [HarnessAdapter] contract, the harness registry, and the shared
/// line-scanning / discovery helpers every adapter builds on.
///
/// Adapters are READ-ONLY over foreign stores: every operation here only
/// reads. Writes go through the FA session repo in [runImport] alone.
library;

import 'dart:convert';
import 'dart:typed_data';

import '../env/execution_env.dart';
import 'foreign_session.dart';

/// Harnesses with a pinned format and a shipped adapter (kimi/opencode ship
/// only after their discovery spike, GOAL AC7/K1). The `--harness` name set
/// lives in `cli_args.dart` (`importHarnessNames`).
const implementedHarnesses = {'omp', 'claude'};

/// The expected foreign store root for [harness] under [homeDir] — the path
/// exit 2 names (and the path an unpinned harness's message points at).
String expectedStoreRoot(String harness, String homeDir) => switch (harness) {
  'omp' => '$homeDir/.omp/agent/sessions',
  'kimi' => '$homeDir/.kimi',
  'opencode' => '$homeDir/.local/share/opencode',
  'claude' => '$homeDir/.claude/projects',
  _ => '$homeDir/.$harness',
};

/// One harness's foreign-session adapter: discovery (current folder only)
/// plus a full read of one session's active branch.
abstract interface class HarnessAdapter {
  /// The harness id (`omp`, `claude`).
  String get id;

  /// The store root under [homeDir] (for messages; never written).
  String storeRoot(String homeDir);

  /// The store root when it exists on [fs], else null (exit-2 class).
  Future<String?> existingRoot({
    required FileSystem fs,
    required String homeDir,
  });

  /// Discovers the sessions recorded for [cwd] (and only [cwd]) in this
  /// harness's store, newest first.
  ///
  /// Bucket matching is by slug COMPARE against the store's directory
  /// names — never by decoding a slug (dash-ambiguous, GOAL E12) — and the
  /// header cwd recorded inside each file is the tiebreak.
  Future<List<ForeignSessionSummary>> discover({
    required FileSystem fs,
    required String cwd,
    required String homeDir,
    required String tempDir,
    required ImportLimits limits,
  });

  /// Reads one session fully: the active (leaf-path) branch, root-first.
  Future<ForeignParseResult> read({
    required FileSystem fs,
    required ForeignSessionSummary summary,
    required String homeDir,
    required ImportLimits limits,
  });
}

/// One scanned JSONL line: [text] when decodable and within the line cap;
/// an oversized or malformed line carries null text (skip-with-count).
final class ForeignLine {
  const ForeignLine(this.number, this.text) : byteLength = null;

  /// An oversized line (over [ImportLimits.maxLineBytes]).
  const ForeignLine.overSized(this.number, this.byteLength)
    : text = null;

  /// An undecodable (non-UTF-8) line.
  const ForeignLine.malformed(this.number)
    : text = null,
      byteLength = null;

  /// 1-based line number.
  final int number;

  /// The decoded line, null when oversized/malformed.
  final String? text;

  /// Byte length for oversized lines.
  final int? byteLength;

  /// Whether the line was oversized.
  bool get isOverSized => byteLength != null;

  /// Whether the line could not be decoded as UTF-8.
  bool get isMalformed => text == null && byteLength == null;
}

/// Streams [path]'s lines one at a time, byte-bounded.
///
/// Ranged backends stream in 1 MiB chunks (complete lines only — bytes
/// carry across chunk borders), so memory stays bounded by the longest
/// line; plain backends fall back to a whole-file text read, still gated
/// by [ImportLimits.maxFileBytes].
Stream<ForeignLine> scanForeignLines(
  FileSystem fs,
  String path,
  ImportLimits limits,
) async* {
  final size = await _fileSize(fs, path);
  if (size < 0) throw ForeignFileError('unreadable file: $path');
  if (size > limits.maxFileBytes) {
    throw ForeignFileError(
      'file too large: $size bytes (limit ${limits.maxFileBytes})',
    );
  }
  if (fs is! RangedReadFileSystem) {
    final read = await fs.readTextFile(path);
    if (read.isErr) throw ForeignFileError('unreadable file: $path');
    var number = 0;
    for (final line in const LineSplitter().convert(read.valueOrNull!)) {
      number++;
      final bytes = utf8.encode(line);
      yield bytes.length > limits.maxLineBytes
          ? ForeignLine.overSized(number, bytes.length)
          : ForeignLine(number, line);
    }
    return;
  }
  const chunkBytes = 1 << 20;
  // The `is!` guard above proved the host is ranged-capable; the explicit
  // bind carries the member (FileSystem itself has no ranged reads).
  final ranged = fs as RangedReadFileSystem;
  var position = 0;
  var number = 0;
  var carry = <int>[];
  while (position < size) {
    final end = position + chunkBytes < size ? position + chunkBytes : size;
    final read = await ranged.readRange(path, position, end);
    if (read.isErr) throw ForeignFileError('unreadable file: $path');
    position = end;
    final bytes = read.valueOrNull ?? Uint8List(0);
    carry.addAll(bytes);
    var newline = carry.indexOf(0x0A);
    while (newline >= 0) {
      number++;
      yield _lineFromBytes(number, carry.sublist(0, newline), limits);
      carry = carry.sublist(newline + 1);
      newline = carry.indexOf(0x0A);
    }
  }
  if (carry.isNotEmpty) {
    number++;
    yield _lineFromBytes(number, carry, limits);
  }
}

ForeignLine _lineFromBytes(int number, List<int> bytes, ImportLimits limits) {
  if (bytes.isNotEmpty && bytes.last == 0x0D) {
    bytes = bytes.sublist(0, bytes.length - 1);
  }
  if (bytes.length > limits.maxLineBytes) {
    return ForeignLine.overSized(number, bytes.length);
  }
  try {
    return ForeignLine(number, utf8.decode(bytes));
  } on FormatException {
    return ForeignLine.malformed(number);
  }
}

Future<int> _fileSize(FileSystem fs, String path) async {
  final info = await fs.fileInfo(path);
  if (info.isErr || info.valueOrNull!.kind != FileKind.file) return -1;
  return info.valueOrNull!.size;
}

/// Lists the `*.jsonl` session files directly under [dir] (files only;
/// tombstones and sidecar dirs never match the `.jsonl` suffix rule),
/// newest mtime first.
Future<List<(String path, int size, int mtimeMs)>> listSessionFiles(
  FileSystem fs,
  String dir,
) async {
  final listed = await fs.listDir(dir);
  if (listed.isErr) return const [];
  final files = <(String path, int size, int mtimeMs)>[];
  for (final entry in listed.valueOrNull ?? const <FileInfo>[]) {
    if (entry.kind != FileKind.file) continue;
    if (!entry.name.endsWith('.jsonl')) continue;
    files.add((entry.path, entry.size, entry.mtimeMs));
  }
  files.sort((a, b) => b.$3.compareTo(a.$3));
  return files;
}

/// Whether [headerCwd] names [cwd]: trailing-slash-insensitive string
/// equality — the discovery tiebreak (GOAL E12: slugs are dash-ambiguous,
/// so discovery never decodes one).
bool headerCwdMatches(String headerCwd, String cwd) {
  String trimSlash(String path) =>
      path.replaceAll(RegExp(r'[/\\]+$'), '');
  return trimSlash(headerCwd) == trimSlash(cwd) && headerCwd.isNotEmpty;
}

/// First-line preview text, ≤160 chars with an ellipsis (GOAL F11) and
/// newlines flattened.
String previewLine(String text) {
  final flat = text.replaceAll('\n', ' ').trim();
  return flat.length > 160 ? '${flat.substring(0, 160)}…' : flat;
}

/// The tree skeleton of one foreign file: a tree record (with id/parentId)
/// or an always-include line (title slot, header, aux records).
final class TreeShell {
  /// Creates a tree-record shell.
  const TreeShell(this.lineNumber, this.id, this.parentId) : isAux = false;

  /// Creates an always-include (non-tree) line shell.
  const TreeShell.aux(this.lineNumber)
    : id = null,
      parentId = null,
      isAux = true;

  /// 1-based source line number.
  final int lineNumber;

  /// The record id (null for aux lines).
  final String? id;

  /// The parent record id (null for roots and aux lines).
  final String? parentId;

  /// Whether the line is always included (title slot/header/aux records).
  final bool isAux;
}

/// Resolves the active branch the way omp's loader does (last entry is the
/// leaf; walk `parentId` to root, stopping on a repeated id to bound
/// corrupt cycles or a dangling parent): the id set of the leaf path, plus
/// how many tree records sit OFF the path (counted skipped).
({Set<String> pathIds, int skippedOffPath}) activeBranchIds(
  List<TreeShell> shells,
) {
  final byId = <String, TreeShell>{
    for (final shell in shells)
      if (!shell.isAux && shell.id != null) shell.id!: shell,
  };
  TreeShell? leaf;
  for (final shell in shells.reversed) {
    if (!shell.isAux && shell.id != null) {
      leaf = shell;
      break;
    }
  }
  if (leaf == null) {
    return (pathIds: const <String>{}, skippedOffPath: 0);
  }
  final pathIds = <String>{};
  final visited = <String>{};
  TreeShell? current = leaf;
  while (current != null && !current.isAux && current.id != null) {
    if (!visited.add(current.id!)) break;
    pathIds.add(current.id!);
    final parent = current.parentId;
    current = parent == null ? null : byId[parent];
  }
  var skippedOffPath = 0;
  for (final shell in shells) {
    if (shell.isAux || shell.id == null) continue;
    if (!pathIds.contains(shell.id)) skippedOffPath++;
  }
  return (pathIds: pathIds, skippedOffPath: skippedOffPath);
}

/// Decodes one JSONL line into a JSON object, or null when the line is not
/// a JSON object (caller counts the skip).
Map<String, dynamic>? decodeJsonLine(String line) {
  try {
    final decoded = jsonDecode(line);
    return decoded is Map<String, dynamic> ? decoded : null;
  } on FormatException {
    return null;
  }
}

