/// A conversation message (`type:"message"`).
final class ForeignMessage extends ForeignRecord {
  /// Creates [ForeignMessage].
  const ForeignMessage({
    required super.lineNumber,
    required this.role,
    required this.contents,
    required this.rawMessage,
