+      if (i + 1 >= args.length) {
+        throw CliArgsException('$name requires a value\n$_importUsage');
+      }
+      value = args[++i];
+    }
+    switch (name) {
+      case '--harness':
+        operands.harness = value;
+      case '--session':
+        operands.session = value;
+      case '--session-root':
+        operands.sessionRoot = value;
+      case '--cwd':
+        operands.cwd = value;
+    }
+  }
+  _validateImportOperands(operands);
+  return operands;
+}
