  expect(sessions, hasLength(1));
  final bucketDir = Directory(
    '${faRoot.path}/${encodeSessionCwd(project.path)}',
  );
  expect(bucketDir.existsSync(), isTrue);
  expect(bucketDir.listSync().whereType<File>(), hasLength(1));

